/// reCAPTCHA v3 site key for release web builds (Phase 12).
/// Passed at build time: --dart-define=RECAPTCHA_SITE_KEY=...
/// A site key is public by design (it ships in every web page), but we still
/// keep it out of the code.
const _recaptchaSiteKey = String.fromEnvironment('RECAPTCHA_SITE_KEY');

/// How the app starts:
/// 1. The native splash (drawn by the system) stays up until the Flutter
///    splash has drawn its first frame, which looks exactly the same.
/// 2. The Flutter splash animates while [_start] connects to Firebase and
///    checks the saved sign-in. No fixed delay: it leaves when that's done.
/// 3. Then: signed in → chats; signed out → sign-in (or, from Round B, the
///    welcome tour on a first visit). See [AuthGate].
Future<void> main() async {
  // Needed before calling any plugin ahead of runApp.
  final binding = WidgetsFlutterBinding.ensureInitialized();
  FlutterNativeSplash.preserve(widgetsBinding: binding);

  // The fonts are bundled in the app (assets/google_fonts): never download
  // them from Google at runtime.
  GoogleFonts.config.allowRuntimeFetching = false;
  _registerFontLicences();

  // Device-only settings. Reading them is quick (no network).
  final prefs = DevicePrefs();
  final introSeen = await prefs.splashIntroSeen();

  runApp(
    NovaApp(
      home: SplashScreen(
        playIntro: !introSeen,
        onIntroPlayed: prefs.setSplashIntroSeen,
        onFirstFrame: FlutterNativeSplash.remove,
        load: () => _start(prefs),
      ),
    ),
  );
}

/// Connects to Firebase, builds the app's services and checks the saved
/// sign-in. Returns the screen that comes after the splash.
Future<Widget> _start(DevicePrefs prefs) async {
  try {
    // Connect to our Firebase project, using the settings for this platform
    // (web or Android).
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );

    // App Check must start BEFORE the AI service is created. Settings from
    // the Firebase console (model name, system prompt) load at the same
    // time, to start faster; if they fail, the built-in defaults are used.
    final config = ConfigService();
    await Future.wait([_activateAppCheck(), config.load()]);

    final ai = AiService(
      appCheck: FirebaseAppCheck.instance,
      modelName: config.aiModel,
      systemPrompt: config.systemPrompt,
    );
    if (kDebugMode) {
      final promptSource = ai.systemPrompt == defaultSystemPrompt
          ? 'built-in'
          : 'Remote Config';
      debugPrint(
        'Nova is using model "${ai.modelName}" '
        '($promptSource system prompt)',
      );
    }

    final auth = AuthService();
    final services = AppServices(
      auth: auth,
      account: AccountService(auth: auth),
      chat: ChatRepository(),
      ai: ai,
      memory: MemoryRepository(),
      projects: ProjectRepository(),
      artifacts: ArtifactRepository(),
      saved: SavedRepository(),
      feedback: FeedbackRepository(),
    );

    // Firebase's first answer about the saved sign-in (or none), and
    // whether this device has seen the welcome tour.
    final (user, onboardingSeen) = await (
      auth.authStateChanges().first.timeout(
        const Duration(seconds: 10),
        onTimeout: () => auth.currentUser,
      ),
      prefs.onboardingSeen(),
    ).wait;

    return AuthGate(
      services: services,
      signInChecked: true,
      initialUser: user,
      onboardingSeen: onboardingSeen,
      prefs: prefs,
    );
  } catch (error, stack) {
    // Technical details only in debug builds (security rule 8).
    if (kDebugMode) {
      debugPrint('Startup failed: $error\n$stack');
    }
    return const _StartupErrorScreen();
  }
}

/// App Check proves requests come from our real app, not a copy or a script.
///
/// Debug builds use the debug provider: the browser console prints a debug
/// token that you register once in the Firebase console.
/// Release builds use reCAPTCHA (web) or Play Integrity (Android).
///
/// If App Check fails to start, the app still opens (sign-in keeps working);
/// protected requests are then refused by Firebase, which is the safe way to
/// fail, and the AI shows "We couldn't verify this app".
Future<void> _activateAppCheck() async {
  if (kIsWeb && kReleaseMode && _recaptchaSiteKey.isEmpty) {
    // No site key yet (set up in Phase 12).
    return;
  }
  try {
    await FirebaseAppCheck.instance.activate(
      providerWeb: kDebugMode
          ? WebDebugProvider()
          : ReCaptchaV3Provider(_recaptchaSiteKey),
      providerAndroid: kDebugMode
          ? const AndroidDebugProvider()
          : const AndroidPlayIntegrityProvider(),
    );
  } catch (error) {
    // Common on web after a hot restart: the browser still holds the first
    // App Check setup, which keeps working. A full restart clears this.
    if (kDebugMode) debugPrint('App Check did not start: $error');
  }
}

/// Adds the fonts' SIL Open Font Licences to Flutter's licence page.
void _registerFontLicences() {
  const fonts = {
    'Space Grotesk': 'assets/licenses/spacegrotesk-OFL.txt',
    'DM Sans': 'assets/licenses/dmsans-OFL.txt',
    'DM Mono': 'assets/licenses/dmmono-OFL.txt',
  };
  LicenseRegistry.addLicense(() async* {
    for (final MapEntry(key: name, value: path) in fonts.entries) {
      yield LicenseEntryWithLineBreaks([
        name,
      ], await rootBundle.loadString(path));
    }
  });
}

/// The root of the app. [home] is the splash, which then replaces itself
/// with the right screen.
class NovaApp extends StatelessWidget {
  const NovaApp({super.key, required this.home});

  final Widget home;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: AppConstants.appName,
      debugShowCheckedModeBanner: false,
      // Studio redesign: dark only for now.
      theme: AppTheme.dark,
      home: home,
    );
  }
}

/// Shown only if Firebase cannot start. Friendly message, no raw error.
class _StartupErrorScreen extends StatelessWidget {
  const _StartupErrorScreen();

  @override
  Widget build(BuildContext context) {
    return const Scaffold(
      body: Center(
        child: Padding(
          padding: EdgeInsets.all(NovaSpace.xl),
          child: Text(
            '${AppConstants.appName} couldn\'t start. '
            'Please check your connection and reload.',
            textAlign: TextAlign.center,
          ),
        ),
      ),
    );
  }
}
